// Get all currently selected tokens on the canvas
const tokens = game.user.targets;

// Check if any tokens are selected
if (tokens.length === 0) {
  ui.notifications.warn("Please select at least one token!");
} else {
  // Loop through each selected token and update its actor's HP
  for (let token of tokens) {
    const actor = token.actor;
    const maxHP = actor.system.health.max; // Path for V10+ systems

    // Update the actor's current HP to match their max HP
    await actor.update({ "system.health.value": maxHP });
    await actor.update({ "system.risk.value": 0 });
  }
  ui.notifications.info(`${token.name} ends combat!`);
}
